from taf.ue.iphone.exceptions import ApnNotProvidedError, NoIpError


def get_iphone_ip(ue_pc, ue_id, logger, apn=None):
    """

    :param ue_pc:   Rpc object responsible for HTTP/HTTPS request
    :param ue_id:   id of iphone, e.g. 00008101-000144860011401E
    :param logger:
    :param apn:
    :return:
    """
    iphone_ips = ue_pc.get_ue_info(ue_id=ue_id, ue_attributes=['ips'])['ips']
    logger.debug(f"getting iphone ip: {iphone_ips}")
    if iphone_ips == {}:
        raise NoIpError("Iphone didn't get any IP address.")
    elif iphone_ips and apn and apn in iphone_ips:
        return iphone_ips[apn][0]
    elif iphone_ips and apn and apn not in iphone_ips:
        raise NoIpError(f"Iphone didn't get IP address for \"{apn}\" APN"
                        f" - got IP for following APNs: {list(iphone_ips.keys())}")
    elif len(iphone_ips) == 1:
        return list(iphone_ips.values())[0][0]
    else:
        raise ApnNotProvidedError(f"Iphone got more than one IP: {iphone_ips}"
                                  "- you have to specify which should be used.\n"
                                  "Add \"apn=<apn_name>\" param to Start Data Transfer keyword")
